use super::*;

/// Read both configurations out of `console/model-defaults.json`.
///
/// Fails loudly rather than substituting a default. A mode assembled from a guess is worse than no
/// mode: it would write a provider/model pair into a project's session file that nothing in the app
/// agrees with, and the session would die on a 401 against a service the user is not running — which
/// is the exact failure `session.json` was introduced to end.
pub fn mode_defaults() -> Result<ModeDefaults, String> {
    let raw = bsc_util::packaged::read("console/model-defaults.json")?;
    let v: serde_json::Value =
        serde_json::from_str(&raw).map_err(|e| format!("console/model-defaults.json is not valid JSON: {e}"))?;
    let s = |k: &str| -> Result<String, String> {
        v.get(k)
            .and_then(|x| x.as_str())
            .map(str::to_string)
            .ok_or_else(|| format!("console/model-defaults.json must carry a string `{k}`"))
    };
    Ok(ModeDefaults {
        anthropic_model: s("anthropicModel")?,
        local_model: s("localModel")?,
        local_base_url: s("localBaseUrl")?,
        local_num_ctx: v
            .get("localNumCtx")
            .and_then(serde_json::Value::as_u64)
            .ok_or("console/model-defaults.json must carry a number `localNumCtx`")?,
    })
}
